#pragma once
// C3 ARCADE 1-bit sprites for a 128x64 monochrome OLED (ESP32-C3).
// Generated from the supplied sheets. Format is XBM/U8g2: bit 0 is the left-most
// pixel of each byte and a 1 lights the OLED pixel. All assets are in flash.
#include <stdint.h>
#if defined(ARDUINO_ARCH_ESP32) || defined(ESP32)
  #include <pgmspace.h>
#else
  #ifndef PROGMEM
    #define PROGMEM
  #endif
#endif

#define C3A_SCREEN_W 128
#define C3A_SCREEN_H 64
#define C3A_BMP_BYTES(w, h) ((((w) + 7) / 8) * (h))
#if defined(__cplusplus)
  #define C3A_STATIC_ASSERT(expr, msg) static_assert((expr), msg)
#elif defined(__STDC_VERSION__) && __STDC_VERSION__ >= 201112L
  #define C3A_STATIC_ASSERT(expr, msg) _Static_assert((expr), msg)
#else
  // Older C compilers still build the data; validate with the included report.
  #define C3A_STATIC_ASSERT(expr, msg)
#endif

typedef struct { const uint8_t* data; uint16_t width; uint16_t height; } C3ASprite;

// U8g2 example: u8g2.drawXBM(x, y, sprite.width, sprite.height, sprite.data);
// Optional bounds-safe helper (C++ only; in C call drawXBM directly).
#ifdef __cplusplus
template <typename Display>
inline void c3aDrawSprite(Display& display, int16_t x, int16_t y, const C3ASprite& sprite) {
  if (x >= C3A_SCREEN_W || y >= C3A_SCREEN_H || x + sprite.width <= 0 || y + sprite.height <= 0) return;
  display.drawXBM(x, y, sprite.width, sprite.height, sprite.data);
}
#endif

